import { render } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import {
  type Conversation,
  type FlowEdge,
  type FlowNode,
  type Flow as FlowType,
  FlowEdgeType,
  FlowNodeType,
} from "../types";
import { Flow } from "./Flow";

let capturedProps: Record<string, unknown> = {};

vi.mock("reactflow", () => ({
  ReactFlowProvider: ({ children }: { children: React.ReactNode }) => <div>{children}</div>,
}));

vi.mock("../CanvasContext", () => ({
  CanvasContextProvider: (props: Record<string, unknown>) => {
    capturedProps = props;
    return <div data-testid="canvas-provider" />;
  },
}));

vi.mock("../canvas/Canvas", () => ({
  Canvas: () => <div data-testid="canvas" />,
}));

const mockFlowStepTrail = vi.fn();
vi.mock("../utils", () => ({
  flowStepTrail: (...args: unknown[]) => mockFlowStepTrail(...args) as Record<string, string[]>,
}));

// --- helpers ---

const makeNode = (id: string, type = FlowNodeType.Message): FlowNode =>
  ({ id, label: id, type, metadata: { x: 0, y: 0 } }) as FlowNode;

const makeEdge = (sourceId: string, targetId: string): FlowEdge => ({
  sourceId,
  targetId,
  type: FlowEdgeType.Auto,
});

function makeConversation(events: Conversation["events"] = []): Conversation {
  return {
    events,
    id: "test-conversation",
    reviewed: false,
    startDate: "2026-01-01T00:00:00.000Z",
    totalNumberOfUserMessages: 0,
  };
}

function makeFlow(overrides?: Partial<FlowType>): FlowType {
  return {
    id: "test-flow",
    name: "Test Flow",
    nodes: [
      makeNode("START", FlowNodeType.Start),
      makeNode("step-1"),
      makeNode("step-2"),
      makeNode("step-3"),
    ],
    edges: [
      makeEdge("START", "step-1"),
      makeEdge("step-1", "step-2"),
      makeEdge("step-2", "step-3"),
    ],
    ...overrides,
  };
}

// --- tests ---

describe("Flow component - collectHighlightedEdges", () => {
  it("sets activeNodeId to the last step in the trail", () => {
    mockFlowStepTrail.mockReturnValue({
      "test-flow": ["START", "step-1", "step-2"],
    });

    render(<Flow flow={makeFlow()} conversation={makeConversation()} />);

    expect(capturedProps.activeNodeId).toBe("step-2");
  });

  it("sets activeNodeId to null when trail is empty", () => {
    mockFlowStepTrail.mockReturnValue({ "test-flow": [] });

    render(<Flow flow={makeFlow()} conversation={makeConversation()} />);

    expect(capturedProps.activeNodeId).toBeNull();
  });

  it("sets activeNodeId to null when flow id has no trail", () => {
    mockFlowStepTrail.mockReturnValue({});

    render(<Flow flow={makeFlow()} conversation={makeConversation()} />);

    expect(capturedProps.activeNodeId).toBeNull();
  });

  it("highlights edges along the step trail", () => {
    mockFlowStepTrail.mockReturnValue({
      "test-flow": ["START", "step-1", "step-2"],
    });

    render(<Flow flow={makeFlow()} conversation={makeConversation()} />);

    const highlightedEdges = capturedProps.highlightedEdges as FlowEdge[];
    expect(highlightedEdges).toContainEqual(makeEdge("START", "step-1"));
    expect(highlightedEdges).toContainEqual(makeEdge("step-1", "step-2"));
  });

  it("does not highlight edges beyond the trail", () => {
    mockFlowStepTrail.mockReturnValue({
      "test-flow": ["START", "step-1"],
    });

    render(<Flow flow={makeFlow()} conversation={makeConversation()} />);

    const highlightedEdges = capturedProps.highlightedEdges as FlowEdge[];
    expect(highlightedEdges).not.toContainEqual(makeEdge("step-1", "step-2"));
    expect(highlightedEdges).not.toContainEqual(makeEdge("step-2", "step-3"));
  });

  it("highlights nodes along the step trail", () => {
    mockFlowStepTrail.mockReturnValue({
      "test-flow": ["START", "step-1", "step-2"],
    });

    render(<Flow flow={makeFlow()} conversation={makeConversation()} />);

    const highlightedNodes = capturedProps.highlightedNodes as FlowNode[];
    const highlightedIds = highlightedNodes.map((n) => n.id);
    expect(highlightedIds).toContain("START");
    expect(highlightedIds).toContain("step-1");
    expect(highlightedIds).toContain("step-2");
  });

  it("does not highlight nodes beyond the trail", () => {
    mockFlowStepTrail.mockReturnValue({
      "test-flow": ["START", "step-1"],
    });

    render(<Flow flow={makeFlow()} conversation={makeConversation()} />);

    const highlightedNodes = capturedProps.highlightedNodes as FlowNode[];
    const highlightedIds = highlightedNodes.map((n) => n.id);
    expect(highlightedIds).not.toContain("step-2");
    expect(highlightedIds).not.toContain("step-3");
  });

  it("finds shortest path when trail has non-adjacent steps", () => {
    mockFlowStepTrail.mockReturnValue({
      "test-flow": ["START", "step-2"],
    });

    render(<Flow flow={makeFlow()} conversation={makeConversation()} />);

    const highlightedEdges = capturedProps.highlightedEdges as FlowEdge[];
    expect(highlightedEdges).toContainEqual(makeEdge("START", "step-1"));
    expect(highlightedEdges).toContainEqual(makeEdge("step-1", "step-2"));
  });

  it("returns empty arrays when no conversation events", () => {
    mockFlowStepTrail.mockReturnValue({});

    render(<Flow flow={makeFlow()} />);

    expect(capturedProps.highlightedEdges).toEqual([]);
    expect(capturedProps.highlightedNodes).toEqual([]);
    expect(capturedProps.activeNodeId).toBeNull();
  });

  it("passes flowName derived from flow.name", () => {
    mockFlowStepTrail.mockReturnValue({});

    render(<Flow flow={makeFlow({ name: "My Flow" })} />);

    expect(capturedProps.flowName).toBe("My Flow");
  });

  it("falls back to flow.id for flowName when name is empty", () => {
    mockFlowStepTrail.mockReturnValue({});

    render(<Flow flow={makeFlow({ name: "", id: "fallback-id" })} />);

    expect(capturedProps.flowName).toBe("fallback-id");
  });
});

describe("Flow component - selectedNodeId pins active node", () => {
  it("sets activeNodeId to selectedNodeId while keeping full trail highlighted", () => {
    mockFlowStepTrail.mockReturnValue({
      "test-flow": ["START", "step-1", "step-2", "step-3"],
    });

    render(<Flow flow={makeFlow()} conversation={makeConversation()} selectedNodeId="step-1" />);

    expect(capturedProps.activeNodeId).toBe("step-1");
    expect(capturedProps.highlightedEdges).toEqual([
      makeEdge("START", "step-1"),
      makeEdge("step-1", "step-2"),
      makeEdge("step-2", "step-3"),
    ]);
  });

  it("keeps full trail highlighted when step appears multiple times", () => {
    mockFlowStepTrail.mockReturnValue({
      "test-flow": ["START", "step-1", "step-2", "step-1", "step-2", "step-3"],
    });

    render(<Flow flow={makeFlow()} conversation={makeConversation()} selectedNodeId="step-1" />);

    expect(capturedProps.activeNodeId).toBe("step-1");
    const highlightedNodes = capturedProps.highlightedNodes as FlowNode[];
    const highlightedIds = highlightedNodes.map((n) => n.id);
    expect(highlightedIds).toContain("step-2");
    expect(highlightedIds).toContain("step-3");
  });

  it("falls back to full trail when selectedNodeId is not in the trail", () => {
    mockFlowStepTrail.mockReturnValue({
      "test-flow": ["START", "step-1", "step-2"],
    });

    render(
      <Flow flow={makeFlow()} conversation={makeConversation()} selectedNodeId="unrelated-step" />,
    );

    expect(capturedProps.activeNodeId).toBe("step-2");
    expect(capturedProps.highlightedEdges).toEqual([
      makeEdge("START", "step-1"),
      makeEdge("step-1", "step-2"),
    ]);
  });

  it("behaves like no selection when selectedNodeId is undefined", () => {
    mockFlowStepTrail.mockReturnValue({
      "test-flow": ["START", "step-1", "step-2"],
    });

    render(<Flow flow={makeFlow()} conversation={makeConversation()} />);

    expect(capturedProps.activeNodeId).toBe("step-2");
    expect(capturedProps.highlightedEdges).toEqual([
      makeEdge("START", "step-1"),
      makeEdge("step-1", "step-2"),
    ]);
  });
});
